function buildPathMap(name,chapter,boss,stage,total,branches){const nodes={};const inBranchDistance=d=>branches.find(b=>d>b.at&&d<b.rejoin);for(let d=0;d<=total;d++){const branch=branches.find(b=>b.at===d),inside=inBranchDistance(d);if(inside){['u','l'].forEach(lane=>{const id=`${d}${lane}`,type=lane==='u'?(d%2?'xp':'heal'):(d%2?'battle':'damage');nodes[id]={id,d,lane,type,x:60+d*105,y:lane==='u'?78:222,next:[]}})}else{const id=`${d}c`,type=d===0?'start':d===total?'boss':branch?'branch':d%7===0?'mini':d%5===0?'heal':d%4===0?'xp':d%3===0?'damage':'battle';nodes[id]={id,d,lane:'c',type,x:60+d*105,y:150,next:[]}}}Object.values(nodes).forEach(node=>{if(node.d===total)return;const branch=branches.find(b=>b.at===node.d);if(branch){node.next=[`${node.d+1}u`,`${node.d+1}l`];return}const rejoin=branches.find(b=>b.rejoin===node.d+1);if(rejoin&&node.lane!=='c'){node.next=[`${node.d+1}c`];return}const nextLane=inBranchDistance(node.d+1)?node.lane:'c';node.next=[`${node.d+1}${nextLane}`]});return{name,chapter,boss,stage,total,nodes,start:'0c'}}
