function openBossChoice(){const map=pathMaps[state.board];$('#choiceKicker').textContent='BOSS SQUARE';$('#choiceTitle').textContent=`${map.boss==='mayu'?'まゆ':'こうき'}のマスに到着！`;$('#choiceText').textContent='今すぐ戦う？ それともスタートへ戻ってレベルを上げる？';$('#routeChoices').classList.add('hidden');$('#bossChoices').classList.remove('hidden');$('#mapChoice').classList.remove('hidden');$('#fightBossBtn').onclick=()=>{$('#mapChoice').classList.add('hidden');startPathBoss()};$('#returnStartBtn').onclick=()=>{$('#mapChoice').classList.add('hidden');state.boardNode=map.start;state.boardPos=0;delete state.pendingNext;showPathMap('レベルと持ち物を保ったまま、スタートへ戻った！')}}
function chooseNextNode(map,node,lane){if(node.next.length<2)return node.next[0];return node.next.find(id=>id.endsWith(lane))||node.next[0]}
async function rollPathRoulette(){if(rouletteBusy)return;normalizePathState();const map=pathMaps[state.board],startNode=map.nodes[state.boardNode],remaining=map.total-startNode.d;if(!remaining){openBossChoice();return}rouletteBusy=true;$('#advanceBtn').disabled=true;const display=$('#rouletteNumber');display.classList.add('spinning');let result=1;for(let i=0;i<13;i++){result=1+Math.floor(Math.random()*6);display.textContent=result;beep(300+i*24,.035);await wait(65+i*5)}display.classList.remove('spinning');if(result>remaining){rouletteBusy=false;$('#advanceBtn').disabled=false;$('#mapMessage').textContent=`${result}！ ボスまであと${remaining}マス。ぴったりではないので、その場にとどまった！`;beep(145,.18);return}for(let step=0;step<result;step++){let node=map.nodes[state.boardNode],next;if(node.next.length>1){let lane=state.pendingNext;if(!lane)lane=await openRouteChoice();next=chooseNextNode(map,node,lane);delete state.pendingNext}else next=node.next[0];state.boardNode=next;state.boardPos=map.nodes[next].d;renderPathNodes(true);beep(420+step*25,.05);await wait(430)}renderPathNodes(false);save();const landed=map.nodes[state.boardNode];if(landed.type==='branch'){state.pendingNext=await openRouteChoice();showPathMap(`${state.pendingNext==='u'?'上':'下'}の道を選んだ！ 次のルーレットで進もう！`);return}await resolvePathSquare(landed.type)}
async function resolvePathSquare(type){if(type==='battle'){beginMobBattle();battle.boardBattle=true;battle.pathBoard=true;battle.boardKind='battle';return}if(type==='mini'){beginPathMini();return}if(type==='boss'){openBossChoice();return}const s=stats();if(type==='damage'){const damage=Math.max(3,Math.round(s.maxHp*(state.board?.24:.16)));state.hp=Math.max(1,state.hp-damage);showPathMap(`💥 危険なマス！ HPが ${damage}減った！`);beep(110,.18);return}if(type==='heal'){const beforeHp=state.hp,beforeMp=state.mp;state.hp=Math.min(s.maxHp,state.hp+Math.round(s.maxHp*.45));state.mp=Math.min(s.maxMp,state.mp+Math.round(s.maxMp*.35));showPathMap(`💚 回復マス！ HP＋${state.hp-beforeHp}、MP＋${state.mp-beforeMp}！`);beep(720,.18);return}if(type==='xp'){const amount=xpForBoardLevels(state.board?7:2),levels=addExp(amount),nextStats=stats();if(levels){state.hp=nextStats.maxHp;state.mp=nextStats.maxMp;state.waters=3}showPathMap(`⭐ 経験値 ${amount}！ レベルが ${levels}上がった！`);beep(900,.2);return}showPathMap()}
function beginPathMini(){const index=state.board?5:0,m=miniBosses[index],lv=Math.min(MAX_LEVEL,state.level+2),maxHp=55+lv*8;battle={enemies:[{name:m.name,icon:m.icon,lv,maxHp,currentHp:maxHp,atk:6+lv*.95,spd:5+lv*1.25,xp:40+lv*10,id:0}],boss:false,miniBoss:true,boardBattle:true,pathBoard:true,boardKind:'mini',lost:false,guard:false};startBattle(`小ボス・${m.name}が あらわれた！`)}
function startPathBoss(){const map=pathMaps[state.board];beginBoss(map.boss);battle.boardBattle=true;battle.pathBoard=true;battle.boardKind='boss'}
function pathWin(){playMusic('victory',true);battle.lost=false;const xp=battle.enemies.reduce((sum,e)=>sum+e.xp,0),levels=addExp(xp),newStats=stats();state.totalWins++;state.score+=xp*10+Math.max(0,state.hp)*3;if(levels){state.hp=newStats.maxHp;state.mp=newStats.maxMp;state.waters=3;state.carrots=Math.min(5,state.carrots+1)}else state.mp=Math.min(newStats.maxMp,state.mp+4);if(battle.boardKind==='boss'){if(battle.boss==='mayu'){state.board=1;state.boardNode=pathMaps[1].start;state.boardPos=0;state.stage=5;state.carrots=5;state.pendingMapMessage='まゆを倒した！ こうきへ続く最終マップが現れた！'}else state.finished=true}else state.pendingMapMessage=battle.boardKind==='mini'?'小ボスを撃破！ 止まったマスから再開！':'敵を倒した！ 止まったマスから再開！';save();show('#resultScreen');$('#resultKicker').textContent=battle.boardKind==='boss'?'BOSS DEFEATED!':battle.boardKind==='mini'?'MINI BOSS DEFEATED!':'VICTORY!';$('#resultIcon').textContent=battle.boardKind==='boss'?'👑':battle.boardKind==='mini'?'🐾':'🏆';$('#resultTitle').textContent=battle.boss==='mayu'?'まゆに勝った！':battle.boss==='kouki'?'こうきを倒した！':`${battle.enemies.length}体を倒した！`;$('#resultText').innerHTML=`経験値 <b>${xp}</b> を てにいれた！<br>たるとは レベル${state.level}。${levels?'<br>お水の回数が3回に戻った！':''}`;$('#levelUp').classList.toggle('hidden',!levels);$('#levelUp').textContent=levels?`LEVEL UP!　${levels>1?'×'+levels:''}`:'LEVEL UP!';$('#resultBtn').textContent=state.finished?'エンディングへ':'すごろくへ戻る';beep(880,.18)}
const winBeforePath=win;
win=function(){if(battle&&battle.pathBoard)return pathWin();return winBeforePath()};
function pathAfterResult(){if(!battle||!battle.pathBoard)return boardAfterResult();if(battle.lost){state=fresh();showPathMap('勇者たるとの冒険が、もう一度はじまる！');return}if(state.finished){ending();return}const message=state.pendingMapMessage;delete state.pendingMapMessage;showPathMap(message)}
