function createRouteMapV2(name,chapter,boss,stage,hard=false){const base=[
  ['s',0,70,260,'start',['m1']],['m1',1,200,260,'battle',['m2']],['m2',2,330,260,'heal',['f1']],['f1',3,460,260,'branch',['t1','b1']],
  ['t1',4,590,150,hard?'battle':'xp',['t2']],['t2',5,720,85,'battle',['t3']],['t3',6,850,75,'heal',['t4']],['t4',7,980,105,'mini',['t5']],['t5',8,1110,150,'xp',['t6']],['t6',9,1240,205,'battle',['merge']],
  ['b1',4,590,360,'battle',['b2']],['b2',5,720,425,'damage',['f2']],['f2',6,850,390,'branch',['u1','l1']],
  ['u1',7,980,320,'heal',['u2']],['u2',8,1110,310,'xp',['u3']],['u3',9,1240,235,'battle',['merge']],
  ['l1',7,980,470,'damage',['l2']],['l2',8,1110,455,hard?'mini':'battle',['l3']],['l3',9,1240,350,'xp',['merge']],
  ['merge',10,1370,260,'heal',['e1']],['e1',11,1500,260,'mini',['e2']],['e2',12,1630,260,'battle',['boss']],['boss',13,1770,260,'boss',[]]
];const nodes=Object.fromEntries(base.map(([id,d,x,y,type,next])=>[id,{id,d,x,y,type,next}]));if(hard){nodes.m2.type='xp';nodes.t3.type='battle';nodes.merge.type='xp';nodes.u1.type='battle'}return{name,chapter,boss,stage,total:13,start:'s',nodes,width:1860}}
const routeMapsV2=[createRouteMapV2('まゆへの冒険ロード','MAP 1・MAYU ROUTE','mayu',0),createRouteMapV2('こうきの最終試験ロード','MAP 2・KOUKI ROUTE','kouki',5,true)];
function normalizeRouteV2(){if(!Number.isFinite(state.board))state.board=0;state.board=Math.min(1,state.board);const map=routeMapsV2[state.board];if(!state.routeNode||!map.nodes[state.routeNode])state.routeNode=map.start;state.stage=map.stage;state.boardPos=map.nodes[state.routeNode].d}
function renderRouteV2(walking=false){normalizeRouteV2();const map=routeMapsV2[state.board],wrap=$('#mapNodes'),scale=innerHeight<720?.75:1;wrap.className='map-nodes route-board-v2';wrap.style.width=`${map.width}px`;wrap.innerHTML='';const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('class','route-svg');svg.setAttribute('viewBox',`0 0 ${map.width} ${520*scale}`);Object.values(map.nodes).forEach(node=>node.next.forEach(id=>{const next=map.nodes[id],line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',node.x);line.setAttribute('y1',node.y*scale);line.setAttribute('x2',next.x);line.setAttribute('y2',next.y*scale);svg.appendChild(line)}));wrap.appendChild(svg);[['上ルート：回復・経験値多め',760,25],['下ルート：戦闘・危険多め',720,495]].forEach(([textValue,x,y])=>{const label=document.createElement('span');label.className='route-label';label.textContent=textValue;label.style.left=`${x}px`;label.style.top=`${y*scale}px`;wrap.appendChild(label)});const current=map.nodes[state.routeNode];Object.values(map.nodes).forEach(node=>{const info=squareInfo[node.type]||['🔀','分岐'],el=document.createElement('span');el.className=`map-node ${node.type}${node.id===state.routeNode?' current':''}${node.d<current.d?' visited':''}`;el.style.left=`${node.x}px`;el.style.top=`${node.y*scale}px`;el.innerHTML=`<b>${info[0]}</b><small>${node.d}</small>`;el.setAttribute('aria-label',`${node.d}マス目 ${info[1]}`);if(node.id===state.routeNode){const token=document.createElement('img');token.className=`board-token${walking?' walking':''}`;token.src='assets/taruto-card-v1.png';token.alt='現在地・たると';el.appendChild(token)}wrap.appendChild(el)});requestAnimationFrame(()=>{const currentElement=wrap.querySelector('.current');if(currentElement)currentElement.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'})})}
function showRouteMapV2(custom){normalizeRouteV2();playMusic('map');show('#mapScreen');const map=routeMapsV2[state.board],node=map.nodes[state.routeNode],s=stats(),remaining=map.total-node.d;renderRouteV2();$('#mapBackdrop').classList.toggle('final-map',state.board===1);$('#mapLevel').textContent=`${state.level}/${MAX_LEVEL}`;$('#mapHp').textContent=`${state.hp}/${s.maxHp}`;$('#mapCarrots').textContent=state.carrots;$('#chapterLabel').textContent=map.chapter;$('#locationName').textContent=map.name;$('#mapMessage').textContent=custom||'道は線でつながっている。分岐で好きなルートを選ぼう！';$('#goalDistance').textContent=remaining?`ボスまで あと${remaining}マス`:'ボスマスに到着！';$('#advanceBtn').textContent=remaining?'ルーレットを回す！':'ボスへの挑戦を選ぶ';$('#advanceBtn').disabled=false;rouletteBusy=false;save()}
