async function rollRouteV3(){if(rouletteBusy)return;normalizeRouteV2();const map=routeMapsV2[state.board],current=map.nodes[state.routeNode],remaining=map.total-current.d;if(!remaining){askBossV2();return}rouletteBusy=true;$('#advanceBtn').disabled=true;const display=$('#rouletteNumber');display.classList.add('spinning');let result=1;for(let i=0;i<12;i++){result=1+Math.floor(Math.random()*3);display.textContent=result;beep(330+i*25,.035);await wait(70+i*5)}display.classList.remove('spinning');if(result>remaining){rouletteBusy=false;$('#advanceBtn').disabled=false;$('#mapMessage').textContent=`${result}！ ボスまであと${remaining}マス。ぴったりではないので進まない！`;beep(145,.18);return}for(let step=0;step<result;step++){const node=map.nodes[state.routeNode];let next;if(node.next.length>1){next=state.routeNext||await askRouteV2(node);delete state.routeNext}else next=node.next[0];await moveTokenV3(next);beep(440+step*35,.06)}save();const landed=map.nodes[state.routeNode];if(landed.type==='branch'){state.routeNext=await askRouteV2(landed);showRouteMapV3('進むルートを決めた！ 次のルーレットで出発！');return}await resolveRouteV2Square(landed.type)}
$('#advanceBtn').onclick=rollRouteV3;
function renderSugorokuV4(){normalizeRouteV2();const map=routeMapsV2[state.board],wrap=$('#mapNodes'),scale=innerHeight<720?.75:1,current=map.nodes[state.routeNode];wrap.className='sugoroku-board';wrap.style.width=`${map.width}px`;wrap.innerHTML='';const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('class','sugoroku-lines');svg.setAttribute('viewBox',`0 0 ${map.width} ${520*scale}`);Object.values(map.nodes).forEach(node=>node.next.forEach(id=>{const next=map.nodes[id],line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',node.x);line.setAttribute('y1',node.y*scale);line.setAttribute('x2',next.x);line.setAttribute('y2',next.y*scale);svg.appendChild(line)}));wrap.appendChild(svg);Object.values(map.nodes).forEach(node=>{const info=squareInfo[node.type]||['🔀','分岐'],el=document.createElement('div');el.className=`sugoroku-node ${node.type}${node.id===state.routeNode?' current':''}`;el.dataset.node=node.id;el.style.left=`${node.x}px`;el.style.top=`${node.y*scale}px`;el.innerHTML=`<span class="node-icon">${info[0]}</span><strong class="node-label">${routeSpaceLabels[node.type]}</strong><small class="node-number">${node.d}</small>`;el.setAttribute('aria-label',`${node.d}マス目 ${routeSpaceLabels[node.type]}`);wrap.appendChild(el)});const token=document.createElement('img');token.id='sugorokuToken';token.className='sugoroku-token';token.src='assets/taruto-card-v1.png';token.alt='たるとの現在地';token.style.left=`${current.x}px`;token.style.top=`${current.y*scale}px`;wrap.appendChild(token);setTimeout(()=>centerSugorokuV4(state.routeNode,false),40)}
function centerSugorokuV4(id,smooth=true){const map=routeMapsV2[state.board],node=map.nodes[id],viewport=$('#mapBackdrop');if(node&&viewport)viewport.scrollTo({left:Math.max(0,node.x-viewport.clientWidth/2),behavior:smooth?'smooth':'auto'})}
async function moveSugorokuV4(id){const map=routeMapsV2[state.board],node=map.nodes[id],scale=innerHeight<720?.75:1,token=$('#sugorokuToken');state.routeNode=id;state.boardPos=node.d;$$('.sugoroku-node').forEach(el=>el.classList.toggle('current',el.dataset.node===id));if(token){token.classList.add('walking');token.style.left=`${node.x}px`;token.style.top=`${node.y*scale}px`}centerSugorokuV4(id,true);await wait(540);if(token)token.classList.remove('walking')}
function showSugorokuV4(custom){normalizeRouteV2();playMusic('map');show('#mapScreen');const map=routeMapsV2[state.board],node=map.nodes[state.routeNode],s=stats(),remaining=map.total-node.d;renderSugorokuV4();$('#mapBackdrop').classList.toggle('final-map',state.board===1);$('#mapLevel').textContent=`${state.level}/${MAX_LEVEL}`;$('#mapHp').textContent=`${state.hp}/${s.maxHp}`;$('#mapCarrots').textContent=state.carrots;$('#chapterLabel').textContent=map.chapter;$('#locationName').textContent=map.name;$('#mapMessage').textContent=custom||'丸の中のアイコンと種類を見て、線に沿って進もう！';$('#goalDistance').textContent=remaining?`ボスまで あと${remaining}マス`:'ボスマスに到着！';$('#advanceBtn').textContent=remaining?'ルーレットを回す！（1〜3）':'ボスへの挑戦を選ぶ';$('#advanceBtn').disabled=false;rouletteBusy=false;save()}
showRouteMapV2=showSugorokuV4;showMap=showSugorokuV4;
async function rollSugorokuV4(){if(rouletteBusy)return;normalizeRouteV2();const map=routeMapsV2[state.board],current=map.nodes[state.routeNode],remaining=map.total-current.d;if(!remaining){askBossV2();return}rouletteBusy=true;$('#advanceBtn').disabled=true;const display=$('#rouletteNumber');display.classList.add('spinning');let result=1;for(let i=0;i<12;i++){result=1+Math.floor(Math.random()*3);display.textContent=result;beep(330+i*25,.035);await wait(70+i*5)}display.classList.remove('spinning');if(result>remaining){rouletteBusy=false;$('#advanceBtn').disabled=false;$('#mapMessage').textContent=`${result}！ ボスまであと${remaining}マス。ぴったりではないので進まない！`;beep(145,.18);return}for(let step=0;step<result;step++){const node=map.nodes[state.routeNode];let next;if(node.next.length>1){next=state.routeNext||await askRouteV2(node);delete state.routeNext}else next=node.next[0];await moveSugorokuV4(next);beep(440+step*35,.06)}save();const landed=map.nodes[state.routeNode];if(landed.type==='branch'){state.routeNext=await askRouteV2(landed);showSugorokuV4('進むルートを決めた！ 次のルーレットで出発！');return}await resolveRouteV2Square(landed.type)}
$('#advanceBtn').onclick=rollSugorokuV4;
const fitBoardY=y=>60+y*.78;
function renderSugorokuFit(){normalizeRouteV2();const map=routeMapsV2[state.board],wrap=$('#mapNodes'),current=map.nodes[state.routeNode];wrap.className='sugoroku-board';wrap.style.width=`${map.width}px`;wrap.innerHTML='';const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('class','sugoroku-lines');svg.setAttribute('viewBox',`0 0 ${map.width} 520`);svg.setAttribute('preserveAspectRatio','none');Object.values(map.nodes).forEach(node=>node.next.forEach(id=>{const next=map.nodes[id],line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',node.x);line.setAttribute('y1',fitBoardY(node.y));line.setAttribute('x2',next.x);line.setAttribute('y2',fitBoardY(next.y));svg.appendChild(line)}));wrap.appendChild(svg);Object.values(map.nodes).forEach(node=>{const info=squareInfo[node.type]||['🔀','分岐'],el=document.createElement('div');el.className=`sugoroku-node ${node.type}${node.id===state.routeNode?' current':''}`;el.dataset.node=node.id;el.style.left=`${node.x}px`;el.style.top=`${fitBoardY(node.y)/520*100}%`;el.innerHTML=`<span class="node-icon">${info[0]}</span><strong class="node-label">${routeSpaceLabels[node.type]}</strong><small class="node-number">${node.d}</small>`;el.setAttribute('aria-label',`${node.d}マス目 ${routeSpaceLabels[node.type]}`);wrap.appendChild(el)});const token=document.createElement('img');token.id='sugorokuToken';token.className='sugoroku-token';token.src='assets/taruto-card-v1.png';token.alt='たるとの現在地';token.style.left=`${current.x}px`;token.style.top=`${fitBoardY(current.y)/520*100}%`;wrap.appendChild(token);setTimeout(()=>centerSugorokuV4(state.routeNode,false),40)}
async function moveSugorokuFit(id){const map=routeMapsV2[state.board],node=map.nodes[id],token=$('#sugorokuToken');state.routeNode=id;state.boardPos=node.d;$$('.sugoroku-node').forEach(el=>el.classList.toggle('current',el.dataset.node===id));if(token){token.classList.add('walking');token.style.left=`${node.x}px`;token.style.top=`${fitBoardY(node.y)/520*100}%`}centerSugorokuV4(id,true);await wait(540);if(token)token.classList.remove('walking')}
renderSugorokuV4=renderSugorokuFit;
moveSugorokuV4=moveSugorokuFit;
async function tapRoulette(){const trigger=$('#rouletteTrigger');if(rouletteBusy||trigger.disabled)return;trigger.disabled=true;try{await rollSugorokuV4()}finally{trigger.disabled=false}}
$('#rouletteTrigger').onclick=tapRoulette;
let rouletteCycleTimer=null,rouletteCycleValue=1;
function stopRouletteCycle(){if(rouletteCycleTimer){clearInterval(rouletteCycleTimer);rouletteCycleTimer=null}const trigger=$('#rouletteTrigger');if(trigger)trigger.classList.remove('cycling')}
function startRouletteCycle(){stopRouletteCycle();const trigger=$('#rouletteTrigger'),display=$('#rouletteNumber');if(!trigger||!display||$('#mapScreen').classList.contains('hidden'))return;trigger.disabled=false;trigger.classList.remove('confirmed');trigger.classList.add('cycling');display.textContent=rouletteCycleValue;rouletteCycleTimer=setInterval(()=>{rouletteCycleValue=rouletteCycleValue%3+1;display.textContent=rouletteCycleValue},95)}
const showSugorokuBeforeCycle=showSugorokuV4;
showSugorokuV4=function(custom){showSugorokuBeforeCycle(custom);setTimeout(startRouletteCycle,120)};
showRouteMapV2=showSugorokuV4;showMap=showSugorokuV4;
async function advanceFixedRoulette(result){normalizeRouteV2();const map=routeMapsV2[state.board],current=map.nodes[state.routeNode],remaining=map.total-current.d;if(!remaining){askBossV2();return}if(result>remaining){rouletteBusy=false;$('#mapMessage').textContent=`${result}！ ボスまであと${remaining}マス。ぴったりではないので進まない！`;beep(145,.18);setTimeout(startRouletteCycle,650);return}for(let step=0;step<result;step++){const node=map.nodes[state.routeNode];let next;if(node.next.length>1){next=state.routeNext||await askRouteV2(node);delete state.routeNext}else next=node.next[0];await moveSugorokuV4(next);beep(440+step*35,.06)}save();const landed=map.nodes[state.routeNode];if(landed.type==='branch'){state.routeNext=await askRouteV2(landed);showSugorokuV4('進むルートを決めた！ 次のルーレットで出発！');return}await resolveRouteV2Square(landed.type)}
async function stopAndAdvanceRoulette(){if(rouletteBusy||!rouletteCycleTimer)return;rouletteBusy=true;const trigger=$('#rouletteTrigger'),display=$('#rouletteNumber'),result=rouletteCycleValue;stopRouletteCycle();trigger.disabled=true;trigger.classList.add('confirmed');display.textContent=result;beep(920,.18);$('#mapMessage').textContent=`${result}で確定！ たるとが進むよ！`;await wait(850);trigger.classList.remove('confirmed');await advanceFixedRoulette(result);if(!$('#mapScreen').classList.contains('hidden')&&!rouletteCycleTimer&&!rouletteBusy)startRouletteCycle()}
$('#rouletteTrigger').onclick=stopAndAdvanceRoulette;
const enemyActionBeforeStun=enemyAction;
enemyAction=async function(enemy,s){if(enemy.stunTurns>0){enemy.stunTurns--;renderEnemies();updateBattle();log(`${enemy.name}は 目を回して動けない！\n残り ${enemy.stunTurns}回`);beep(210,.12);await wait(560);return}return enemyActionBeforeStun(enemy,s)};
const heroActionBeforeAdvanced=heroAction;
heroAction=async function(type,s){const buffWasActive=battle.heroAtkBuffTurns>0,boosted={...s,atk:s.atk*(buffWasActive?1.5:1)},target=activeEnemy(),advanced=['dig','snack','tackle','father','motherSupport','rampage','supreme'].includes(type);if(!advanced){await heroActionBeforeAdvanced(type,boosted);if(buffWasActive)battle.heroAtkBuffTurns--;return}let text='';state.mp-=skills[type].mp;if(type==='dig'){battle.evadeNext=true;text='たるとは 穴を掘ってかくれた！\n次の攻撃を1回だけ完全回避！';beep(280,.14)}if(type==='snack'){battle.heroAtkBuffTurns=3;text='たるとは おやつを食べた！\n攻撃力が1.5倍！ 3回継続！';beep(780,.16)}if(type==='tackle'){const dmg=Math.max(1,Math.round(boosted.atk*.5));target.currentHp-=dmg;showNumber(dmg,'damage',target);hitEnemies(false);text=`先制！ たるとタックル！\n${target.name}に ${dmg}ダメージ！`;beep(670,.13)}if(type==='father'){const hpBefore=state.hp,mpBefore=state.mp;state.hp=Math.min(s.maxHp,state.hp+Math.round(s.maxHp*.25));state.mp=Math.min(s.maxMp,state.mp+Math.round(s.maxMp*.2));showNumber(state.hp-hpBefore,'heal');text=`とーちゃんの応援！\nHP＋${state.hp-hpBefore}、MP＋${state.mp-mpBefore}！`;beep(820,.18)}if(type==='motherSupport'){const hpHeal=s.maxHp-state.hp,mpHeal=s.maxMp-state.mp;state.hp=s.maxHp;state.mp=s.maxMp;battle.heroAtkBuffTurns=2;showNumber(hpHeal,'heal');text=`かーちゃんの応援！\nHP・MP全回復！ 攻撃力1.5倍が2回！`;beep(940,.2)}if(type==='rampage'){let total=0;aliveEnemies().forEach(e=>{const dmg=Math.max(5,Math.round(boosted.atk*3*(.9+Math.random()*.2)));e.currentHp-=dmg;total+=dmg;showNumber(dmg,'critical',e)});hitEnemies(true);text=`たると大暴走！！\n敵全体に合計 ${total}ダメージ！`;beep(105,.24)}if(type==='supreme'){const dmg=100+Math.floor(Math.random()*201);target.currentHp-=dmg;battle.damageHalfTurns=3;showNumber(dmg,'critical',target);hitEnemies(false);text=`天上天下唯我独尊！！\n${target.name}に ${dmg}ダメージ！ 受けるダメージ半減が3回！`;beep(1020,.25)}if(buffWasActive&&!['snack','motherSupport'].includes(type))battle.heroAtkBuffTurns--;log(text);updateBattle();await wait(720)};
const enemyActionBeforeAdvanced=enemyAction;
enemyAction=async function(enemy,s){if(enemy.stunTurns>0)return enemyActionBeforeAdvanced(enemy,s);if(battle.evadeNext){battle.evadeNext=false;log(` ${enemy.name}の攻撃！\nたるとは穴にかくれて完全回避！`);beep(360,.14);await wait(560);return}const hpBefore=state.hp;await enemyActionBeforeAdvanced(enemy,s);if(battle.damageHalfTurns>0&&state.hp<hpBefore){const raw=hpBefore-state.hp,restored=Math.floor(raw/2);state.hp+=restored;battle.damageHalfTurns--;showNumber(restored,'heal');log(`天上天下唯我独尊の守り！\n受けたダメージを ${raw-restored} に半減！ 残り${battle.damageHalfTurns}回`);updateBattle();await wait(380)}};
function showLevelStatus(){if(!pendingLevelDetails)return;const d=pendingLevelDetails,round=n=>Math.round(n);$('#levelBefore').textContent=d.beforeLevel;$('#levelAfter').textContent=d.afterLevel;$('#hpBefore').textContent=round(d.before.maxHp);$('#hpAfter').textContent=round(d.after.maxHp);$('#mpBefore').textContent=round(d.before.maxMp);$('#mpAfter').textContent=round(d.after.maxMp);$('#atkBefore').textContent=round(d.before.atk);$('#atkAfter').textContent=round(d.after.atk);$('#defBefore').textContent=round(d.before.def);$('#defAfter').textContent=round(d.after.def);$('#spdBefore').textContent=round(d.before.spd);$('#spdAfter').textContent=round(d.after.spd);$('#levelStatus').classList.remove('hidden');beep(980,.2)}
$('#levelStatus').onclick=()=>{$('#levelStatus').classList.add('hidden');pendingLevelDetails=null};
